export const getCreateLabComparisonUrl = (profileId: number,) => {




  return `/api/profiles/${profileId}/lab-comparisons`
}

/**
 * @summary Submit baseline and/or follow-up lab values and get progress insights
 */
export const createLabComparison = async (profileId: number,
    labComparisonInput: LabComparisonInput, options?: RequestInit): Promise<LabComparison> => {

  return customFetch<LabComparison>(getCreateLabComparisonUrl(profileId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(labComparisonInput)
  }
);}




export const getCreateLabComparisonMutationOptions = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof createLabComparison>>, TError,{profileId: number;data: BodyType<LabComparisonInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof createLabComparison>>, TError,{profileId: number;data: BodyType<LabComparisonInput>}, TContext> => {

const mutationKey = ['createLabComparison'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof createLabComparison>>, {profileId: number;data: BodyType<LabComparisonInput>}> = (props) => {
          const {profileId,data} = props ?? {};

          return  createLabComparison(profileId,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type CreateLabComparisonMutationResult = NonNullable<Awaited<ReturnType<typeof createLabComparison>>>
    export type CreateLabComparisonMutationBody = BodyType<LabComparisonInput>
    export type CreateLabComparisonMutationError = ErrorType<unknown>

    /**
 * @summary Submit baseline and/or follow-up lab values and get progress insights
 */
export const useCreateLabComparison = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof createLabComparison>>, TError,{profileId: number;data: BodyType<LabComparisonInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof createLabComparison>>,
        TError,
        {profileId: number;data: BodyType<LabComparisonInput>},
        TContext
      > => {
      return useMutation(getCreateLabComparisonMutationOptions(options));
    }

